var n=`0208-pimientos-de-padron`;var t=`world-0208`;var a=`ES`;var s=`southern-europe`;var o=4;var r=10;var d={en:`Pimientos de Padrón`,ua:`Перець падрон`};var l={en:`A traditional Spain dish made with padrón pepper, flaky sea salt. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Іспанія. Основні інгредієнти: перець падрон, морська сіль пластівцями. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var p=[{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 9 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 9 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:9,i:[[`padron-pepper`,500,`g`],[`extra-virgin-olive-oil`,45,`ml`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:1,i:[[`flaky-sea-salt`,6,`g`]]}];var h={slug:n,id:t,country:`ES`,region:s,servings:4,minutes:10,title:d,text:l,steps:p};export{a as country,h as default,t as id,r as minutes,s as region,o as servings,n as slug,p as steps,l as text,d as title};